  def test_leave(self):
    self.driver.get("http://localhost:5173/login")
    self.driver.maximize_window()

    # 1. Login with student account
    WebDriverWait(self.driver, 10).until(
        expected_conditions.presence_of_element_located((By.NAME, "email"))
    )
    email_input = self.driver.find_element(By.NAME, "email")
    email_input.clear()
    email_input.send_keys("divinbabu2027@mca.ajce.in")

    password_input = self.driver.find_element(By.NAME, "password")
    password_input.clear()
    password_input.send_keys("123456")

    self.driver.find_element(By.XPATH, "//button[@type='submit']").click()

    # 2. Wait for redirect to student portal
    WebDriverWait(self.driver, 10).until(
        expected_conditions.url_contains("/student")
    )

    # 3. Navigate to Student Leaves
    self.driver.get("http://localhost:5173/student/leaves")

    # 4. Click 'Apply for Leave' button
    apply_btn = WebDriverWait(self.driver, 10).until(
        expected_conditions.element_to_be_clickable(
            (By.XPATH, "//button[contains(., 'Apply for Leave')]")
        )
    )
    apply_btn.click()

    # 5. Fill Leave Form Modal
    date_inputs = WebDriverWait(self.driver, 10).until(
        expected_conditions.presence_of_all_elements_located((By.XPATH, "//input[@type='date']"))
    )
    date_inputs[0].send_keys("2026-10-15")
    date_inputs[1].send_keys("2026-10-16")

    reason_textarea = self.driver.find_element(By.TAG_NAME, "textarea")
    reason_textarea.clear()
    reason_textarea.send_keys("Medical leave - recovering from fever.")

    # 6. Click 'Submit Application'
    submit_btn = self.driver.find_element(By.XPATH, "//button[contains(., 'Submit Application')]")
    submit_btn.click()

    # 7. Wait for submission to complete
    time.sleep(2)

    # 8. Assert leave request processed
    assert "/student/leaves" in self.driver.current_url
    print("\n✅ STUDENT LEAVE TEST PASSED! Leave application submitted successfully.")

